import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    odd = even = 0
    for x in data[1:1 + n]:
        v = int(x)
        if v & 1:
            odd += v
        else:
            even += v
    print(abs(even - odd) if odd & 1 else even + odd)

main()

