def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([2]), fmt([10**9]), fmt([10**9 - 1]), fmt([1, 1]), fmt([2, 4, 6]), fmt([1, 3, 5, 7, 9]), fmt([1, 2, 3, 4, 5]), fmt([3, 5, 4, 10]), fmt([7, 9, 11])]
    for n in (2, 3, 4, 6, 9, 12, 20, 30):
        for _ in range(3):
            hi = rng.choice([5, 20, 1000, 10**9])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt([10**9 - 1] * 100000))
    tests.append(fmt([10**9] * 100000))
    tests.append(fmt([rng.choice([10**9, 10**9 - 1, 1, 2]) for _ in range(100000)]))
    return tests

